import { html } from "../../../../html.js";
import { useState } from "/prototype/vendor/preact-hooks.js";
import PageVariants from "../../ui/PageVariants.js";
import { Dialog, EmptyState, Icon, Tabs } from "../../ui/index.js";
import { organizations, auditEvents } from "./data.js";

function Toast({message}){return message&&html`<div class="p-orgs-toast" role="status">${message}</div>`}
function Header({onCreate}){return html`<header class="p-orgs-head"><div><p>POLICY BOUNDARIES</p><h1>Organizations</h1><span>Set budgets, approvals, access, and connected systems.</span></div><button class="p-orgs-primary" onClick=${onCreate}><${Icon} name="plus"/>Create organization</button></header>`}
function CreateDialog({close,notify}){const [name,setName]=useState("");return html`<${Dialog} onClose=${close}><div class="p-orgs-dialog"><p>NEW POLICY BOUNDARY</p><h2>Create organization</h2><label>Name<input autoFocus value=${name} onInput=${e=>setName(e.target.value)} placeholder="e.g. Product engineering"/></label><label>Monthly budget cap<select><option>$500</option><option>$1,000</option><option>$2,500</option></select></label><label>Approval policy<select><option>Two approvers for protected changes</option><option>Owner approval for releases</option></select></label><div class="p-orgs-actions"><button onClick=${close}>Cancel</button><button class="p-orgs-primary" disabled=${!name.trim()} onClick=${()=>{notify(`${name} created with a draft policy`);close()}}>Create organization</button></div></div></${Dialog}>`}
function Budget({org}){const pct=Math.min(100,Math.round(org.budget/org.budgetCap*100));return html`<div class=${`p-orgs-budget ${pct>=100?'over':''}`}><div><span>MONTHLY BUDGET</span><b>$${org.budget} <small>/ $${org.budgetCap}</small></b></div><i><em class=${pct<55?'low':pct<90?'mid':'high'}></em></i><small>${pct}% allocated</small></div>`}
function Health({org}){return html`<span class=${`p-orgs-health ${org.paused?'paused':org.health==='Over budget'?'over':''}`}><i></i>${org.paused?'Paused':org.health}</span>`}
function OrgDetail({org,notify}){const [tab,setTab]=useState('Overview');const [paused,setPaused]=useState(!!org.paused);const shown={...org,paused};return html`<section class="p-orgs-detail"><header><div class="p-orgs-mark">${org.initials}</div><div><h2>${org.name}</h2><${Health} org=${shown}/></div><button class="p-orgs-quiet" onClick=${()=>{setPaused(!paused);notify(paused?`${org.name} resumed`:`${org.name} paused`)}}>${paused?'Resume organization':'Pause organization'}</button></header><${Tabs} value=${tab} setValue=${setTab} items=${['Overview','Policy','Members','Connectors','Audit']}/><div class="p-orgs-detail-body">${tab==='Overview'&&html`<div class="p-orgs-overview"><${Budget} org=${org}/><article><span>APPROVAL POLICY</span><b>${org.policy}</b><small>Protected changes require an enrolled passkey approver.</small></article><article><span>CONNECTORS</span><b>${org.connectors.join(' · ')}</b><small>All connector health checks are current.</small></article></div>`}${tab==='Policy'&&html`<div class="p-orgs-form"><label>Monthly budget cap<input value=${`$${org.budgetCap}`} readOnly/></label><label>Who may approve<select><option>${org.policy}</option></select></label><label>Approval threshold<select><option>Two passkey-enrolled members</option></select></label><button class="p-orgs-primary" onClick=${()=>notify('Policy changes saved')}>Save policy</button></div>`}${tab==='Members'&&html`<div class="p-orgs-members">${org.approvers.map((person,i)=>html`<article><b>${person}</b><span>${i===0?'Organization owner':'Passkey-enrolled approver'}</span><em>Passkey verified</em></article>`)}<button onClick=${()=>notify('Invite link copied')}>Invite member</button></div>`}${tab==='Connectors'&&html`<div class="p-orgs-connectors">${org.connectors.map(name=>html`<article><b>${name}</b><span>Connected · least-privilege scopes</span><button onClick=${()=>notify(`${name} connector settings opened`)}>Manage</button></article>`)}<button onClick=${()=>notify('Connector catalog opened')}>Add connector</button></div>`}${tab==='Audit'&&html`<ol class="p-orgs-audit">${auditEvents.map((event,i)=>html`<li><i></i><div><b>${event}</b><span>${i+1}h ago · Operator audit trail</span></div></li>`)}</ol>`}</div></section>`}
function Directory({notify}){const [selected,setSelected]=useState(organizations[0]);const [dialog,setDialog]=useState(false);return html`<main class="e-page p-orgs-page"><${Header} onCreate=${()=>setDialog(true)}/><div class="p-orgs-directory"><aside><div class="p-orgs-list-head"><span>ORGANIZATIONS</span><b>${organizations.length}</b></div>${organizations.map(org=>html`<button class=${selected.id===org.id?'selected':''} onClick=${()=>setSelected(org)}><span class="p-orgs-mini-mark">${org.initials}</span><span><b>${org.name}</b><small>${org.members} members · $${org.budgetCap} cap</small></span><${Health} org=${org}/></button>`)}</aside><${OrgDetail} org=${selected} notify=${notify}/></div>${dialog&&html`<${CreateDialog} close=${()=>setDialog(false)} notify=${notify}/>`}</main>`}
function Board({notify}){const [selected,setSelected]=useState(null);const [dialog,setDialog]=useState(false);return html`<main class="e-page p-orgs-page"><${Header} onCreate=${()=>setDialog(true)}/><div class="p-orgs-board-note"><span><i></i> 2 healthy · 1 needs attention</span><button onClick=${()=>notify('Showing organizations with active runs')}>Active runs</button></div><section class="p-orgs-board">${organizations.map(org=>html`<article class=${org.paused?'is-paused':''} onClick=${()=>setSelected(org)} tabindex="0"><header><span class="p-orgs-mark">${org.initials}</span><${Health} org=${org}/></header><h2>${org.name}</h2><p>${org.members} members · ${org.connectors.length} connected systems</p><${Budget} org=${org}/><footer><span>${org.policy}</span><${Icon} name="arrow-up-right"/></footer></article>`)}</section><section class="p-orgs-empty"><${EmptyState}>No other organizations yet. Create one to give work its own policy boundary.</${EmptyState}></section>${selected&&html`<aside class="p-orgs-sheet"><button aria-label="Close organization" onClick=${()=>setSelected(null)}>×</button><div class="p-orgs-mark">${selected.initials}</div><h2>${selected.name}</h2><${Health} org=${selected}/><${Budget} org=${selected}/><dl><div><dt>Approvers</dt><dd>${selected.approvers.join(', ')}</dd></div><div><dt>Connectors</dt><dd>${selected.connectors.join(', ')}</dd></div><div><dt>Latest audit</dt><dd>${selected.audit}</dd></div></dl><button class="p-orgs-primary" onClick=${()=>notify('Organization policy opened')}>Open policy</button></aside>`}${dialog&&html`<${CreateDialog} close=${()=>setDialog(false)} notify=${notify}/>`}</main>`}
function Settings({notify}){const [orgId,setOrgId]=useState(organizations[0].id);const [paused,setPaused]=useState(false);const org=organizations.find(x=>x.id===orgId);return html`<main class="e-page p-orgs-page p-orgs-settings"><${Header} onCreate=${()=>notify('Create organization flow opened')}/><div class="p-orgs-settings-layout"><aside><label>ORGANIZATION<select value=${orgId} onInput=${e=>setOrgId(e.target.value)}>${organizations.map(x=>html`<option value=${x.id}>${x.name}</option>`)}</select></label><nav><a href="#budget">Budget cap</a><a href="#approval">Approval policy</a><a href="#people">Members</a><a href="#systems">Connected systems</a><a href="#danger">Danger zone</a></nav></aside><form onSubmit=${e=>{e.preventDefault();notify('Organization settings saved')}}><header><p>ORGANIZATION SETTINGS</p><h1>${org.name}</h1><${Health} org=${{...org,paused}}/></header><section id="budget"><h2>Budget cap</h2><p>Pause autonomous spending before it exceeds this monthly boundary.</p><label>Monthly cap<input value=${'$'+org.budgetCap} readOnly/></label></section><section id="approval"><h2>Approval policy</h2><p>Specify who can authorize protected work for this organization.</p><label>Policy<select><option>${org.policy}</option></select></label><label>Approvers<input value=${org.approvers.join(', ')} readOnly/></label></section><section id="people"><h2>Members & passkeys</h2>${org.approvers.map(x=>html`<div class="p-orgs-person"><b>${x}</b><span>Passkey enrolled · may approve</span></div>`)}</section><section id="systems"><h2>Connected systems</h2><div class="p-orgs-system-list">${org.connectors.map(x=>html`<span>${x}<i>Connected</i></span>`)}</div></section><section id="danger" class="p-orgs-danger"><h2>Danger zone</h2><p>${paused?'This organization is paused. No new work can start.':'Pause new autonomous work while retaining history and audit records.'}</p><button type="button" onClick=${()=>{setPaused(!paused);notify(paused?'Organization resumed':'Organization paused')}}>${paused?'Resume organization':'Pause organization'}</button></section><footer><button class="p-orgs-primary">Save changes</button></footer></form></div></main>`}
export default function OrgsPage(){const [toast,setToast]=useState('');const notify=message=>{setToast(message);setTimeout(()=>setToast(''),2500)};return html`<${PageVariants} variants=${[{key:'1',name:'Directory',render:()=>html`<${Directory} notify=${notify}/>`},{key:'2',name:'Portfolio',render:()=>html`<${Board} notify=${notify}/>`},{key:'3',name:'Settings',render:()=>html`<${Settings} notify=${notify}/>`}]}/><${Toast} message=${toast}/>`}
